"""Accounts Merge — union-find over email addresses.

Every email in one account is unioned with the account's first email; the groups
that fall out are the merged accounts.

Time: O(N log N) dominated by sorting the emails   Space: O(N)
"""
from collections import defaultdict
from typing import List


class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        parent = {}

        def find(x: str) -> str:
            parent.setdefault(x, x)
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        owner = {}
        for account in accounts:
            name, emails = account[0], account[1:]
            for email in emails:
                owner[email] = name
                if find(email) != find(emails[0]):
                    parent[find(email)] = find(emails[0])

        groups = defaultdict(list)
        for email in owner:
            groups[find(email)].append(email)
        return [[owner[root]] + sorted(members) for root, members in groups.items()]
